<template>
	<div class="history">
       <appHeader :title="tits" :istop="num"></appHeader>
	   <div class="main">
	        <div class="not-lt" v-if="notList.length>0">
		      <div class="not-item" v-for="(item,index) in notList" :key="index">
			    <div class="not-its">
				    <div class="not-its-time">{{item.createDate}}</div>
					<div class="not-title">{{item.title}}</div>
					<div class="not-its-img" v-if="item.picInfo">
					   <img class="not-img"  :src="getImageUrl(item.picInfo)" />
					</div>
					<div class="not-its-name" v-html="item.content"></div>
				</div>
			  </div> 
		    </div>
	        <div class="no-data" v-else>
				<img class="no-imgs" src="@/assets/images/nodata.webp" />
				<div class="no-t">暂无公告</div>
			</div>
	   </div>
	   <div class="footNot" @click="baskHome">
	       <div class="foot-ts" >进入首页</div>
	   </div>
	</div>
</template>
<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { useRouter } from 'vue-router'
import { useUserStore } from '@/store/user'
import { showToast, showConfirmDialog } from 'vant'

// 路由和状态管理
const router = useRouter()
const userStore = useUserStore()
const  notList = ref([])
const userInfo = ref('');
const num =ref (3)
const tits = ref("公告管理")
// 初始化组件
onMounted(() => {
    userInfo.value = JSON.parse(localStorage.getItem('userInfo'));
    const uus = localStorage.getItem('muuids')
    if(userInfo.value.isInit==2&&uus){
        getNotice();
    }
})
const getImageUrl = (base64) =>{
    if (!base64) return '';
    // 识别类型
    let mimeType = 'image/jpeg';
    if (base64.startsWith('iVBOR')) mimeType = 'image/png';
    if (base64.startsWith('R0lGOD')) mimeType = 'image/gif';
    if (base64.startsWith('PHN2Zy')) mimeType = 'image/svg+xml';
    if (base64.startsWith('UklGR')) mimeType = 'image/webp';
    
    return `data:${mimeType};base64,${base64}`;
}
// 处理不同意操作
const getNotice = async () => {
  try {
    let res = await userStore.notice();
	notList.value = res.data
  } catch (error) {
     console.log('退出登录失败')
  }
}
const baskHome = () =>{
	router.push("/home");
}
</script>

